// Recursive Solution (Most common answer)
function flatten(arr) {
  let result = [];
  for (let i = 0; i < arr.length; i++) {
    if (Array.isArray(arr[i])) {
      // If it's an array, recursively flatten it and merge it into result
      result = result.concat(flatten(arr[i]));
    } else {
      // If it's a number/string, just push it
      result.push(arr[i]);
    }
  }
  return result;
}

